function roundedRectShape(w, h, r) {
  const shape = new Shape();
  const wh = w / 2, hh = h / 2;
  shape.moveTo(-wh + r, -hh);
  shape.lineTo(wh - r, -hh);
  shape.quadraticCurveTo(wh, -hh, wh, -hh + r);
  shape.lineTo(wh, hh - r);
  shape.quadraticCurveTo(wh, hh, wh - r, hh);
  shape.lineTo(-wh + r, hh);
  shape.quadraticCurveTo(-wh, hh, -wh, hh - r);
  shape.lineTo(-wh, -hh + r);
  shape.quadraticCurveTo(-wh, -hh, -wh + r, -hh);
  return shape;
}

